<?php
require_once __DIR__.'/../includes/bootstrap.php';
try {
    $db=fleet_db();$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$reg=(string)($_GET['registration']??'');$location=trim((string)($_GET['location']??''));$page=max(1,(int)($_GET['page']??1));$limit=20;$export=(string)($_GET['export']??'')==='1';
    $where=['a.is_active=1'];$params=[];
    if($q!==''){$where[]='(a.primary_identifier LIKE ? OR a.make LIKE ? OR a.model LIKE ? OR EXISTS(SELECT 1 FROM asset_identifiers i WHERE i.asset_id=a.id AND (i.raw_value LIKE ? OR i.normalized_value LIKE ?)))';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like);}
    $typeCodes=['HORSE'=>'TRUCK_HEAD','TANKER'=>'TANKER_TRAILER','FLATBED'=>'FLATBED_TRAILER'];if($type==='TRAILER'){$where[]="t.type_code IN ('TANKER_TRAILER','FLATBED_TRAILER')";}elseif(isset($typeCodes[$type])){$where[]='t.type_code=?';$params[]=$typeCodes[$type];}
    if(in_array($reg,['REGISTERED','UNREGISTERED','UNKNOWN'],true)){$where[]='a.registration_status=?';$params[]=$reg;}
    $clause=implode(' AND ',$where);$sql="SELECT a.id,a.primary_identifier,a.make,a.model,a.registration_status,a.last_seen_at,t.type_name,t.type_code,y.yard_name,pri.source_note,(SELECT COUNT(*) FROM certificate_submissions cs WHERE cs.asset_id=a.id) certificate_count FROM assets a JOIN asset_types t ON t.id=a.asset_type_id LEFT JOIN yards y ON y.id=a.current_yard_id LEFT JOIN asset_identifiers pri ON pri.asset_id=a.id AND pri.is_primary=1 WHERE $clause ORDER BY a.updated_at DESC,a.id DESC";
    $stmt=$db->prepare($sql);$stmt->execute($params);$rawItems=$stmt->fetchAll();$sourceIds=[];foreach($db->query('SELECT id,source_code FROM spreadsheet_sources') as $r)$sourceIds[$r['source_code']]=(int)$r['id'];$sheets=[];foreach($db->query('SELECT id,source_id,sheet_name FROM spreadsheet_sheets') as $r)$sheets[$r['sheet_name'].'|'.$r['source_id']]=(int)$r['id'];$rowStmt=$db->prepare('SELECT raw_data FROM spreadsheet_source_row_versions WHERE sync_run_id=? AND sheet_id=? AND source_row_number=? LIMIT 1');$items=[];$locations=[];
    foreach($rawItems as $item){$item['source_location']=$item['yard_name']??'';$note=(string)($item['source_note']??'');if(preg_match('/^([^\/]+)\/([^\/]+) row (\d+) col ([A-Z]+)/',$note,$m)){$sheet=$m[2];if(str_starts_with($sheet,'Ngwerere_')||$sheet==='Unregistered_Ngwerere')$item['source_location']='Ngwerere';elseif($sheet==='Registered_21Miles')$item['source_location']='21 Miles Yard';elseif(str_starts_with($sheet,'Nakonde_')){$sid=$sheets[$sheet.'|'.($sourceIds[$m[1]]??0)]??0;preg_match('/\(run (\d+)\)/',$note,$rm);$rowStmt->execute([(int)($rm[1]??0),$sid,(int)$m[3]]);$raw=$rowStmt->fetchColumn();$cells=$raw===false?[]:(json_decode((string)$raw,true)?:[]);$yard=trim((string)($cells[$sheet==='Nakonde_Tankers_unregistered'?3:4]??''));$item['source_location']=$yard!==''&&!preg_match('/^(total|nakonde_flatbeds)/i',$yard)?$yard:'Nakonde';}}unset($item['source_note']);$locations[$item['source_location']]=($locations[$item['source_location']]??0)+1;if($location!==''&&$item['source_location']!==$location)continue;$items[]=$item;}
    arsort($locations);$total=count($items);$pageItems=$export?$items:array_slice($items,($page-1)*$limit,$limit);json_response(['ok'=>true,'items'=>$pageItems,'total'=>$total,'pages'=>(int)ceil($total/$limit),'page'=>$page,'locations'=>$locations]);
}catch(Throwable $e){error_log('Fleet asset search: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Search unavailable. Check the database connection.'],500);}
